<script>
import { supportsDesktopHover } from '../utils/desktopHover';
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import SectionMenu from './SectionMenu.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import AiAskTerm from './ui/AiAskTerm.vue';
import SourceViewLinks from './ui/SourceViewLinks.vue';
import GitHubRepoLink from './ui/GitHubRepoLink.vue';
import ViewModeControl from './ui/ViewModeControl.vue';
import CollectionBrowser from './ui/CollectionBrowser.vue';
import { visibleProjectEntries as projectEntries } from '../data/projects';
import { acquireInteractiveCursorLock } from '../utils/interactiveCursorLock';
import { consumeCollectionReturn } from '../utils/askSession';

export default {
  name: 'ProjectsTab',
  components: { AiAskTerm, AiViewTerm, SourceViewLinks, SectionMenu, GitHubRepoLink, ViewModeControl, CollectionBrowser },
  mixins: [scrollRevealMixin],
  data() {
    const collectionReturn = consumeCollectionReturn();
    return {
      searchQuery: '',
      viewMode: collectionReturn?.mode || 'grid',
      viewTransitionActive: false,
      isMobileCollection: false,
      pendingRouteTargetId: '',
      restoredOpenId: collectionReturn?.openId || '',
      restoringCollectionState: Boolean(collectionReturn),
      projectEntries
    };
  },
  computed: {
    searchTerms() {
      return this.searchQuery
        .toLowerCase()
        .split(/[\s,.;:!?()[\]{}"']+/)
        .map((term) => term.trim())
        .filter((term) => term.length >= 2);
    },
    searchActive() {
      return this.searchTerms.length > 0;
    },
    routeTargetId() {
      const raw = (this.$route && this.$route.hash ? this.$route.hash.replace(/^#/, '') : '')
        || (this.$route && this.$route.query ? this.$route.query.to : '')
        || '';
      try {
        return decodeURIComponent(raw);
      } catch (error) {
        return raw;
      }
    },
    hasSearchMatches() {
      return this.projectEntries.some((entry) => this.entryMatches(entry.id));
    },
    visibleProjectEntries() {
      return this.projectEntries.filter((entry) => this.entryMatches(entry.id));
    },
    compactEntries() {
      return this.visibleProjectEntries.map((entry) => ({
        id: entry.id,
        title: entry.title,
        subtitle: entry.subtitle,
        preview: entry.preview,
        body: this.projectDetailBody(entry),
        category: this.groupLabel(entry.group),
        period: entry.period,
        route: entry.route && entry.route !== '/projects' ? entry.route : null,
        externalPage: entry.id === 'slidepoise',
        action: entry.cta || 'Open project',
        images: this.compactMedia(entry),
        galleryClass: this.projectGalleryClass(entry.id),
        lab: this.projectAssociation(entry.id),
        extraLinks: this.projectLinks(entry.id),
        sourceId: `projects:${entry.id}`,
        kind: 'project'
      }));
    },
    chapterItems() {
      return [
        { key: 'personal', id: 'projects-personal', label: 'Personal', title: 'On my own time' },
        { key: 'professional', id: 'projects-professional', label: 'Professional', title: 'Professional and lab work' },
        { key: 'coursework', id: 'projects-coursework', label: 'Coursework' }
      ].filter((item) => this.groupVisible(item.key));
    },
    menuChildren() {
      const out = {};
      for (const item of this.chapterItems) {
        out[item.key] = this.projectEntries
          .filter((entry) => entry.group === item.key && this.entryMatches(entry.id))
          .map((entry) => ({
            id: entry.id,
            label: entry.title,
            subtitle: entry.subtitle || entry.summary || '',
            date: entry.period,
          }));
      }
      return out;
    }
  },
  watch: {
    '$route.hash'() {
      this.handleRouteTargetArrival();
    },
    '$route.query.to'() {
      this.handleRouteTargetArrival();
    },
    searchQuery() {
      this.refreshScrollReveal();
    }
  },
  mounted() {
    try {
      const saved = window.localStorage.getItem('projects-view-mode');
      if (!this.restoringCollectionState && ['expanded', 'grid', 'index'].includes(saved)) this.viewMode = saved;
    } catch (error) {
      // Browsing preferences remain optional when storage is unavailable.
    }
    this.setupCollectionViewport();
    this.handleRouteTargetArrival();
  },
  unmounted() {
    this.teardownCollectionViewport();
  },
  methods: {
    handleRouteTargetArrival() {
      this.pendingRouteTargetId = this.viewMode === 'expanded' ? '' : this.routeTargetId;
    },
    clearPendingRouteTarget(targetId) {
      if (this.pendingRouteTargetId === targetId) this.pendingRouteTargetId = '';
    },
    setupCollectionViewport() {
      this._collectionMobileMedia = window.matchMedia('(max-width: 720px)');
      this._handleCollectionViewport = (event) => {
        this.isMobileCollection = event.matches;
        if (event.matches && this.viewMode === 'grid') this.viewMode = 'index';
      };
      this._handleCollectionViewport(this._collectionMobileMedia);
      if (this._collectionMobileMedia.addEventListener) {
        this._collectionMobileMedia.addEventListener('change', this._handleCollectionViewport);
      } else {
        this._collectionMobileMedia.addListener(this._handleCollectionViewport);
      }
    },
    teardownCollectionViewport() {
      if (!this._collectionMobileMedia || !this._handleCollectionViewport) return;
      if (this._collectionMobileMedia.removeEventListener) {
        this._collectionMobileMedia.removeEventListener('change', this._handleCollectionViewport);
      } else {
        this._collectionMobileMedia.removeListener(this._handleCollectionViewport);
      }
    },
    escapeHtml(text) {
      return String(text == null ? '' : text)
        .split('&').join('&amp;')
        .split('<').join('&lt;')
        .split('>').join('&gt;')
        .split(String.fromCharCode(34)).join('&quot;')
        .split("'").join('&#39;');
    },
    escapeRegExp(text) {
      return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    },
    highlightText(text) {
      const escaped = this.escapeHtml(text);
      const terms = [...new Set(this.searchTerms)]
        .sort((a, b) => b.length - a.length)
        .map((term) => this.escapeRegExp(term));
      if (!terms.length) return escaped;

      const re = new RegExp(`(${terms.join('|')})`, 'gi');
      return escaped.replace(re, '<mark>$1</mark>');
    },
    entryById(id) {
      return this.projectEntries.find((entry) => entry.id === id);
    },
    compactMedia(entry) {
      if (entry.id === 'searchstory') {
        return [{ src: '/assets/img/AIarchive.png', fullSrc: '/assets/img/AIarchive.png', alt: entry.title }];
      }
      if (entry.mediaMode === 'hero') {
        return (entry.media || []).map((src) => ({ src, fullSrc: src, alt: entry.title }));
      }
      if (entry.mediaMode === 'logo') return [];
      const media = entry.id === 'lexaday' ? (entry.media || []).slice(0, 4) : (entry.media || []);
      return media.map((src) => ({
        src: src.includes('/assets/img/') ? src.replace('/assets/img/', '/assets/img/gallery-thumbs/') + '.webp' : src,
        fullSrc: src,
        alt: entry.title
      }));
    },
    projectDetailBody(entry) {
      if (entry.id === 'searchstory') {
        return "<p>This project uses AI to help visitors explore the work, research, photographs, and writing on this site through their own questions. Search opens original passages in context. Ask brings relevant passages together into an answer with citations and optional narration. View composes a reading path using the original projects, images, writing, and interactive components. A saved View preserves its question, page, illustration, narration, and sources at a particular moment. These snapshots make it possible to compare different perspectives on the archive and return to a question as the site grows.</p><p>Try it directly. Press <kbd>/</kbd> or <kbd>&#8984;</kbd> + <kbd>K</kbd> anywhere on the site.</p>";
      }
      return `<p>${this.escapeHtml(entry.summary || '')}</p>`;
    },
    projectGalleryClass(id) {
      return {
        searchstory: 'collection-detail-hero',
        slidepoise: 'collection-detail-hero',
        dealtracker: 'proof-gallery-lg',
        stride: 'proof-gallery-rounded',
        lexaday: 'collection-detail-gallery-compact'
      }[id] || '';
    },
    projectAssociation(id) {
      return {
        insurance: { name: 'HSBC', url: 'https://www.hsbc.com/', logo: '/assets/img/hsbc.png', logoHeight: '5vh' },
        pwcRag: { name: 'PwC', url: 'https://www.pwc.com.hk/', logo: '/assets/img/PwC.png', logoHeight: '6vh' },
        pwcItOps: { name: 'PwC', url: 'https://www.pwc.com.hk/', logo: '/assets/img/PwC.png', logoHeight: '6vh' },
        pds: { name: 'PDS Lab', url: 'https://psym-ds.github.io/' }
      }[id] || null;
    },
    projectLinks(id) {
      return {
        slidepoise: [{ label: 'github.com/henryhyw/slidepoise', url: 'https://github.com/henryhyw/slidepoise' }],
        scrollytelling: [{ label: 'Live demo · henryw.me/CCGL9074', url: 'https://www.henryw.me/CCGL9074/', iconClass: 'fas fa-play-circle' }],
        dealtracker: [{ label: 'github.com/henryhyw/dealtracker', url: 'https://github.com/henryhyw/dealtracker' }],
        stride: [{ label: 'github.com/backprop07/STAT4011', url: 'https://github.com/backprop07/STAT4011' }],
        lexaday: [{ label: 'github.com/henryhyw/lexaday', url: 'https://github.com/henryhyw/lexaday' }],
        pds: [{ label: 'Live demo · llmas.pds-lab.org', url: 'https://llmas.pds-lab.org/', iconClass: 'fas fa-play-circle' }]
      }[id] || [];
    },
    entryMatches(id) {
      const entry = this.entryById(id);
      if (!entry) return false;
      const text = [
        entry.title,
        entry.subtitle,
        entry.summary,
        ...(entry.details || []),
        entry.text
      ].join(' ').toLowerCase();
      return this.searchTerms.every((term) => text.includes(term));
    },
    groupMatches(groupKey) {
      return this.projectEntries
        .filter((entry) => entry.group === groupKey)
        .some((entry) => this.entryMatches(entry.id));
    },
    groupVisible(groupKey) {
      if (!this.searchActive) return true;
      return this.groupMatches(groupKey);
    },
    entryVisible(id) {
      return this.entryMatches(id);
    },
    handleTimelineClick(event) {
      if (!supportsDesktopHover()) return;
      const card = event.target.closest('.timeline-event');
      if (!card) return;
      // Inner links, buttons (e.g. the Seen-in-Views trigger), and zoomable
      // images keep their own behavior; anywhere else opens the project page.
      if (event.target.closest('a, button, [data-full-src]')) return;
      const h3 = card.querySelector('h3');
      const entry = h3 && h3.id ? this.entryById(h3.id) : null;
      if (!entry || !entry.route || entry.route === '/projects') return;
      if (entry.id === 'slidepoise') {
        window.open(entry.route, '_blank', 'noopener');
        return;
      }
      this.$router.push(entry.route).catch(() => {});
    },
    groupLabel(groupKey) {
      const item = this.chapterItems.find((entry) => entry.key === groupKey);
      return item ? item.label : groupKey;
    },
    async setViewMode(mode) {
      if (!['expanded', 'grid', 'index'].includes(mode) || mode === this.viewMode) return;
      try {
        window.localStorage.setItem('projects-view-mode', mode);
      } catch (error) {
        // The selected view still works for this visit without persistence.
      }
      const applyMode = async () => {
        this.viewMode = mode;
        await this.$nextTick();
        this.refreshScrollReveal();
      };
      const reduceMotion = window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (!document.startViewTransition || reduceMotion) {
        applyMode();
        return;
      }
      const releaseCursorLock = acquireInteractiveCursorLock();
      this.viewTransitionActive = true;
      const transitionToken = (this._viewTransitionToken || 0) + 1;
      this._viewTransitionToken = transitionToken;
      await this.$nextTick();
      let transition;
      try {
        transition = document.startViewTransition(applyMode);
      } catch (error) {
        releaseCursorLock();
        this.viewTransitionActive = false;
        await applyMode();
        return;
      }
      transition.finished.catch(() => {}).finally(() => {
        releaseCursorLock();
        if (this._viewTransitionToken === transitionToken) this.viewTransitionActive = false;
      });
    },
    chapterId(groupKey) {
      const item = this.chapterItems.find((entry) => entry.key === groupKey);
      return item ? item.id : '';
    },
    // Toggle disabled: groups stay expanded.
    // toggleGroup(groupKey) {
    //   if (this.searchActive) return;
    //   this.expanded = {
    //     ...this.expanded,
    //     [groupKey]: !this.expanded[groupKey]
    //   };
    //   this.refreshScrollReveal();
    // },
    clearSearch() {
      this.searchQuery = '';
    }
  }
}
</script>

