<template>
  <div class="view-bridge-pair">
    <p class="view-bridge">{{ cleanText }}</p>
    <transition name="translation-reveal">
      <p v-if="translatedText" class="view-bridge-translation" :lang="translationLang">{{ translatedText }}</p>
    </transition>
  </div>
</template>

<script>
export default {
  name: 'ViewBridge',
  props: {
    bridge: {
      type: Object,
      required: true,
    },
    translatedText: { type: String, default: '' },
    translationLang: { type: String, default: 'en-x-mtfrom-und' },
  },
  computed: {
    cleanText() {
      return String(this.bridge?.text || '')
        .replace(/\s*\[[a-z0-9_-]+:[^\]]+\]/gi, '')
        .replace(/\s*\[(?:\d+(?:\s*,\s*\d+)*)\]/g, '')
        .replace(/\s+([.,!?])/g, '$1')
        .trim();
    },
  },
};
</script>

