// Retain hidden records and their assets so publication can be reversed here.
// Public listings and retrieval catalogs share this visibility boundary.
export const visibleProjectEntries = projectEntries.filter((entry) => !entry.hidden);

export function projectById(id) {
  return projectEntries.find((entry) => entry.id === id);
}

export function thumbFor(src) {
  if (!src) return src;
  const prefix = '/assets/img/';
  if (!src.startsWith(prefix)) return src;
  return `${prefix}gallery-thumbs/${src.slice(prefix.length)}.webp`;
}
